"use client";

import { forwardRef } from "react";
import {
  FieldError,
  Label,
  Radio as AriaRadio,
  RadioGroup as AriaRadioGroup,
  Text,
  type RadioGroupProps as AriaRadioGroupProps,
  type RadioProps as AriaRadioProps,
} from "react-aria-components";
import { radioGroupDefaults, type RadioGroupSpecProps } from "../generated/radio-group.types";
import { cx } from "../utils/cx";

export interface RadioGroupProps
  extends RadioGroupSpecProps,
    Omit<AriaRadioGroupProps, keyof RadioGroupSpecProps | "className" | "children"> {
  className?: string;
}

export const RadioGroup = forwardRef<HTMLDivElement, RadioGroupProps>(function RadioGroup(
  {
    label,
    description,
    errorMessage,
    orientation = radioGroupDefaults.orientation,
    isDisabled = radioGroupDefaults.isDisabled,
    // Left undefined unless passed: React Aria treats any defined isInvalid as
    // controlled and would hide its own validation (required, min/max...).
    isInvalid,
    isRequired = radioGroupDefaults.isRequired,
    children,
    className,
    ...rest
  },
  ref,
) {
  return (
    <AriaRadioGroup
      {...rest}
      ref={ref}
      orientation={orientation}
      isDisabled={isDisabled}
      isInvalid={isInvalid}
      isRequired={isRequired}
      className={cx("flex flex-col gap-2", className)}
    >
      <Label className="text-sm font-medium text-[var(--rd-color-text-default)]">
        {label}
        {isRequired && <span aria-hidden="true" className="text-[var(--rd-color-feedback-danger)]"> *</span>}
      </Label>
      <div className={cx("flex gap-2", orientation === "horizontal" ? "flex-row flex-wrap gap-x-5" : "flex-col")}>
        {children}
      </div>
      {description && (
        <Text slot="description" className="text-xs text-[var(--rd-color-text-muted)]">
          {description}
        </Text>
      )}
      <FieldError className="text-xs text-[var(--rd-color-feedback-danger)]">{errorMessage}</FieldError>
    </AriaRadioGroup>
  );
});

export interface RadioProps extends Omit<AriaRadioProps, "className" | "children"> {
  className?: string;
  children: React.ReactNode;
}

export const Radio = forwardRef<HTMLLabelElement, RadioProps>(function Radio({ className, children, ...rest }, ref) {
  return (
    <AriaRadio
      {...rest}
      ref={ref}
      className={cx(
        "group inline-flex items-center gap-2 text-sm text-[var(--rd-color-text-default)] cursor-pointer " +
          "data-[disabled]:opacity-50 data-[disabled]:cursor-not-allowed",
        className,
      )}
    >
      <span
        aria-hidden="true"
        className={
          "size-[18px] shrink-0 rounded-full border transition-[border-width,border-color] group-data-[hovered]:border-[var(--rd-color-action-primary)] group-data-[selected]:[box-shadow:var(--rd-elevation-control)] " +
          "border-[var(--rd-color-border-strong)] bg-[var(--rd-color-surface-default)] " +
          "group-data-[selected]:border-[5px] group-data-[selected]:border-[var(--rd-color-action-primary)] " +
          "group-data-[invalid]:border-[var(--rd-color-feedback-danger)] " +
          "group-data-[focus-visible]:ring-2 group-data-[focus-visible]:ring-offset-2 group-data-[focus-visible]:ring-[var(--rd-color-focus-ring)]"
        }
      />
      {children}
    </AriaRadio>
  );
});

// Generated by rdloom codegen from specs/radio-group.spec.json (v0.1.1).
// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

export const radioGroupOrientationValues = ["vertical", "horizontal"] as const;

/** Lets the user pick exactly one option from a small, visible set. Use with Radio children. */
export interface RadioGroupSpecProps {
  /**
   * Visible group label.
   */
  label: string;
  /**
   * Help text shown under the options.
   */
  description?: string;
  /**
   * Shown when the group is invalid.
   */
  errorMessage?: string;
  /**
   * Layout direction of the options.
   * @default "vertical"
   */
  orientation?: "vertical" | "horizontal";
  /**
   * Controlled selected value.
   */
  value?: string;
  /**
   * Initial value when uncontrolled.
   */
  defaultValue?: string;
  /**
   * Disables every option.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Marks the group as invalid and shows errorMessage.
   * @default false
   */
  isInvalid?: boolean;
  /**
   * Requires a selection for form submission.
   * @default false
   */
  isRequired?: boolean;
  /**
   * Radio options.
   */
  children: ReactNode;
  /**
   * Called with the newly selected value.
   */
  onChange?: (value: string) => void;
}

export const radioGroupDefaults = {
  orientation: "vertical",
  isDisabled: false,
  isInvalid: false,
  isRequired: false,
} as const;

export const radioGroupMeta = {
  "name": "RadioGroup",
  "version": "0.1.1",
  "status": "experimental",
  "role": "radiogroup"
} as const;
